# WRF Extreme Rainfall - 3 sub-layers with scope-aware clipping
# Uses wrf.get_extreme_rainfall_tiles() function for smart date + scope clipping

# Heavy Rainfall
LAYER
    INCLUDE "config/database.map"
    DATA "geom from (select g.id, g.rainfall_mm, g.geom from wrf.get_extreme_rainfall_tiles('%time%', 'f90', NULLIF('%scope%', ''), NULLIF(NULLIF('%project_countries%', '__none__'), '')) g where g.rainfall_mm > 0) as subq using unique id using srid=4326"
    MASK "gha_admin_extent_mask"
    INCLUDE "shared/common-layer-properties.map"
    CLASS
        NAME "Heavy Rainfall"
        STYLE
            COLOR 175 238 238
            OUTLINECOLOR 175 238 238
        END
    END
    METADATA
        "wms_title" "WRF Heavy Rainfall"
        INCLUDE "shared/wms-layer-metadata.map"
    END
    NAME "wrf_extreme_heavy"
    VALIDATION
        "time" "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
        "default_time" "2026-03-05"
        "project_countries" "^[A-Za-z, _]+$"
        "default_project_countries" ""
        "scope" "^[a-z]+$"
        "default_scope" ""
    END
END

